void OopMapCache::enqueue_for_cleanup(OopMapCacheEntry* entry) {
  while (true) {
    OopMapCacheEntry* head = AtomicAccess::load(&_old_entries);
    entry->_next = head;
    if (AtomicAccess::cmpxchg(&_old_entries, head, entry) == head) {
